import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    words = input_data[1:n+1]

    MOD = 10**9 + 7

    def get_variants(s):
        variants = set()
        for i in range(len(s)):
            variants.add(s[:i] + s[i+1:])
        return sorted(list(variants))

    if n == 0:
        print(0)
        return

    prev_variants = get_variants(words[0])
    count = len(prev_variants)

    for i in range(1, n):
        curr_variants = get_variants(words[i])
        new_count = 0
        if not prev_variants or not curr_variants:
            print(0)
            return

        j = 0
        for v in curr_variants:
            while j < len(prev_variants) and prev_variants[j] <= v:
                j += 1
            if j > 0:
                new_count = (new_count + j) % MOD
            else:
                break

        if new_count == 0:
            print(0)
            return

        prev_variants = curr_variants
        count = (count * new_count) % MOD

    print(count)

solve()
